-- PixelRP: the Beauty Salon set, in Builders > Customs > Beauty Salon.
--
-- 28 pieces on ONE page under the existing Customs category: salon
-- chairs, mirror stations, a sink, shelves and the small things that go on
-- them. Generated by docker/nitro/import-pack-tree.py.
--
-- The download's classnames are German (beautyspot_foehn), so every title was
-- written from the furni's own art (SALON_NAMES). None of the 28 repeats a
-- furni we already sell, by name or by image.
--
-- The rendering half is the .nitro bundles, the icons and the FurnitureData
-- entries under nitro/overrides/; the rows below are inert without them.
--
-- Everything is free - the catalog has been since 90_FreeCatalog.
--
-- Idempotent: fixed id ranges, cleared before insert. The sets under Customs are
-- renumbered alphabetically at the end, which lands the same way every run.

SET @builders := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1),
    912362);
SET @customs := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `id` = 944000 LIMIT 1),
    (SELECT `id` FROM `catalog_pages` WHERE `caption` = 'Customs' AND `parent_id` = @builders
        ORDER BY `id` LIMIT 1));

DELETE FROM `catalog_items` WHERE `item_id` BETWEEN 110900 AND 110927;
DELETE FROM `catalog_pages` WHERE `id` BETWEEN 963000 AND 963999;
DELETE FROM `furniture` WHERE `id` BETWEEN 110900 AND 110927;

     `page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
VALUES
    (963000, @customs, 'Beauty Salon', 193, 2, 0, 1, '', 'default_3x3', '', '', b'1', b'1');


-- Furniture. id == sprite_id, the convention every custom line here follows;
-- interaction_modes_count is the bundle's own animation count.


SET @n := 0;
UPDATE `catalog_pages` SET `order_num` = (@n := @n + 1)
    WHERE `parent_id` = @customs
    ORDER BY `caption`;
